import React from 'react'
import { View, ActivityIndicator } from 'react-native'

import { styles } from './styles'

interface LoadType {
    load: boolean;
}

export function LoadIndicator({ load }: LoadType) {
    if (!load) return null;

    return (
        <View style={styles.load}>
            <ActivityIndicator size={25} color='#121212' />
        </View>
    );
};
